INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000030d',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss work and dignity at B2","Use Arbeit und Würde vocabulary","Talk about good work, precarious employment, and the right to work in Germany"],"explanation":{"intro":"Work and dignity vocabulary covers precarious work, decent work, and the German debate about work quality at B2.","culturalNote":"Arbeit und Würde: Key: Art. 1 Grundgesetz — die Würde des Menschen ist unantastbar (human dignity is inviolable — extends to workplace: Würde am Arbeitsplatz). ILO Decent Work Agenda (1999 — Decent Work: productive employment + social protection + rights at work + social dialogue). Key Germany: Arbeitswürde debate — Hartz IV (2003 — stigmatised as Schmarotzer debate). Mindestlohn (minimum wage — €8.50 2015 — €12.41 2024 — controversy over whether it is dignifying). Scheinselbständigkeit (bogus self-employment). Leiharbeit (temporary agency work — precariousness). Werkverträge (service contracts — labour standards circumvention). Key: PSA (Personalserviceagenturen). Kurzarbeit (short-time work). Haushaltsnahe Dienstleistungen (household services — often informal). Burnout (recognised work-related illness in Germany). Recht auf Nichterreichbarkeit (right to digital disconnection — not yet legally enshrined). Work-life-balance. Betriebliche Mitbestimmung (co-determination — Betriebsrat, Aufsichtsrat)."},"examples":[{"german":"Würde bei der Arbeit umfasst mehr als physische Sicherheit — sie umfasst auch das Recht auf Selbstbestimmung, auf sinnvolle Tätigkeit, auf angemessene Entlohnung und auf respektvolle Behandlung. Precäre Beschäftigung untergräbt diese Dimensionen: Wenn Arbeitsverhältnisse kurzfristig, kontrollintensiv und schlecht bezahlt sind, wird Arbeit nicht zur Quelle von Würde und Identität, sondern zur Quelle von Vulnerabilität und Unsicherheit.","english":"Dignity at work encompasses more than physical safety — it also encompasses the right to self-determination, to meaningful activity, to adequate remuneration, and to respectful treatment. Precarious employment undermines these dimensions: when employment relationships are short-term, control-intensive, and poorly paid, work does not become a source of dignity and identity, but a source of vulnerability and insecurity."},{"german":"Die Auseinandersetzung um den Mindestlohn hat gezeigt, dass Arbeit nicht nur eine ökonomische, sondern auch eine normative Dimension hat: Die Forderung, dass Vollzeitarbeit zur Existenzsicherung ausreichen soll — das Lohnabstandsgebot — ist ein Anspruch auf Würde: Wer arbeitet, soll nicht auf ergänzende Sozialleistungen angewiesen sein, weil das Arbeit entwertet und Würde verletzt.","english":"The dispute over the minimum wage has shown that work has not only an economic, but also a normative dimension: the demand that full-time work should be sufficient for securing a livelihood — the wage floor principle — is a claim for dignity: whoever works should not be dependent on supplementary social benefits, because that devalues work and violates dignity."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss dignified work, precarious employment, and the minimum wage debate in Germany at B2."}}',
'{"items":[{"word":"die Würde","translation":"dignity","pronunciation":"dee VÜR-deh","example":"Würde am Arbeitsplatz."},{"word":"precär","translation":"precarious","pronunciation":"preh-KÄR","example":"Precäre Beschäftigung."},{"word":"die Entlohnung","translation":"remuneration","pronunciation":"dee ent-LOH-noong","example":"Angemessene Entlohnung."},{"word":"entwerten","translation":"to devalue","pronunciation":"ent-VER-ten","example":"Arbeit entwerten."},{"word":"angewiesen sein auf","translation":"to be dependent on","pronunciation":"AN-geh-vee-zen zyn owf","example":"Auf Hilfe angewiesen sein."},{"word":"das Lohnabstandsgebot","translation":"wage floor principle","pronunciation":"dahs LOHN-ab-shtants-geh-boht","example":"Lohnabstandsgebot einhalten."}]}',
'{"title":"Etwas umfasst mehr als X — something encompasses more than X","pattern":"etwas umfasst mehr als X = something encompasses more than X (umfassen = to encompass, include — marks that X is too narrow: the thing is broader; often followed by a list of additional dimensions)","explanation":"Umfassen = to encompass, include, comprise (um = around + fassen = to grasp — to grasp around, contain). Mehr als X = more than X (marks that X is insufficient to describe the full scope). Würde bei der Arbeit umfasst mehr als physische Sicherheit = dignity at work encompasses more than physical safety. The pattern expands a concept: not just negating X but showing what else belongs (self-determination, meaningful activity, adequate pay). Compare: geht über X hinaus (goes beyond X — directional), schließt X ein (includes X — more additive), ist nicht auf X zu begrenzen (cannot be limited to X — more restrictive), beinhaltet X und mehr (contains X and more — more cumulative).","examples":[{"sentence":"Gesundheit umfasst mehr als die Abwesenheit von Krankheit.","translation":"Health encompasses more than the absence of disease."},{"sentence":"Demokratie umfasst mehr als das Recht zu wählen.","translation":"Democracy encompasses more than the right to vote."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Precär'' means?","options":["precarious","insecure","temporary","unstable"],"correctAnswer":"precarious"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Dignity at work encompasses more than physical safety — it also encompasses the right to self-determination, to meaningful activity, to adequate remuneration, and to respectful treatment. Precarious employment undermines these dimensions: when employment relationships are short-term, control-intensive, and poorly paid, work does not become a source of dignity and identity, but a source of vulnerability and insecurity.","options":["Würde bei der Arbeit umfasst mehr als physische Sicherheit — sie umfasst auch das Recht auf Selbstbestimmung, auf sinnvolle Tätigkeit, auf angemessene Entlohnung und auf respektvolle Behandlung. Precäre Beschäftigung untergräbt diese Dimensionen: Wenn Arbeitsverhältnisse kurzfristig, kontrollintensiv und schlecht bezahlt sind, wird Arbeit nicht zur Quelle von Würde und Identität, sondern zur Quelle von Vulnerabilität und Unsicherheit.","Würde am Arbeitsplatz bedeutet mehr als sichere Arbeitsbedingungen.","Unsichere Arbeit macht Menschen abhängig und verletzt ihre Würde.","Gute Arbeit muss gut bezahlt, sinnvoll und respektvoll sein."],"correctAnswer":"Würde bei der Arbeit umfasst mehr als physische Sicherheit — sie umfasst auch das Recht auf Selbstbestimmung, auf sinnvolle Tätigkeit, auf angemessene Entlohnung und auf respektvolle Behandlung. Precäre Beschäftigung untergräbt diese Dimensionen: Wenn Arbeitsverhältnisse kurzfristig, kontrollintensiv und schlecht bezahlt sind, wird Arbeit nicht zur Quelle von Würde und Identität, sondern zur Quelle von Vulnerabilität und Unsicherheit."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Gesundheit umfasst mehr als die Abwesenheit von ___.","options":["Krankheit","Schmerz","Leiden","Einschränkung"],"correctAnswer":"Krankheit"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Democracy encompasses more than the right to vote","wordBankItems":["Demokratie","umfasst","mehr","als","das","Recht","zu","wählen","."],"correctAnswer":"Demokratie umfasst mehr als das Recht zu wählen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Angewiesen sein auf'' means?","options":["to be dependent on","to rely on","to need","to require"],"correctAnswer":"to be dependent on"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000030e',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the digital world of work at B2","Use Digitale Arbeitswelt vocabulary","Talk about remote work, algorithmic management, and the future of work in Germany"],"explanation":{"intro":"Digital world of work vocabulary covers remote work, algorithmic management, and Germany''s debates about AI and employment at B2.","culturalNote":"Digitale Arbeitswelt: Germany: Home-Office (remote work — massively increased post-COVID — 25% regularly). Betriebsrat (works council — right to negotiate on home-office conditions). Key: Recht auf Home-Office (right to home office — discussed but not legislated). Algorithmic management (algorithmus-gesteuertes Management — Amazon warehouses, Uber drivers rated and managed by algorithms). Plattformarbeit (platform work — see next lesson). Arbeit 4.0 (Work 4.0 — German government initiative). AI in recruitment (CV screening — bias concerns). Digitale Überwachung (digital surveillance at work — Germany: strong Betriebsrat rights limit this). Key: Work-Life-Blending (blurring of boundaries). Recht auf Nichterreichbarkeit (right to disconnect — France: loi El Khomri 2016 — Germany: no law). DSGVO (GDPR) and employee data. Weiterbildung für digitale Kompetenzen (digital upskilling). Burnout and digital stress. Telearbeit (telework — formal legal framework in Germany)."},"examples":[{"german":"Die Digitalisierung der Arbeitswelt erzeugt ein Paradox der Kontrolle: Einerseits ermöglicht Remote-Arbeit räumliche und zeitliche Flexibilität, die Autonomie steigert; andererseits ermöglicht digitale Infrastruktur eine permanente Überwachung von Produktivität, Anwesenheit und Kommunikation, die tiefere Kontrolle erlaubt als der Großraumbüro-Blick des Vorgesetzten. Algorithmisches Management — die Steuerung von Arbeit durch Software-Systeme — intensiviert diesen Widerspruch.","english":"The digitalisation of the world of work generates a paradox of control: on the one hand, remote work enables spatial and temporal flexibility that increases autonomy; on the other hand, digital infrastructure enables permanent monitoring of productivity, presence, and communication, which allows deeper control than the open-plan office gaze of the supervisor. Algorithmic management — the steering of work by software systems — intensifies this contradiction."},{"german":"Das Recht auf Nichterreichbarkeit adressiert eine strukturelle Grenzauflösung: Wenn Kommunikationsgeräte permanent verfügbar sind und Arbeitgeber erreichbar zu sein erwarten, verschwimmt die Grenze zwischen Arbeitszeit und Freizeit — mit Konsequenzen für Erholung, Gesundheit und Familienleben. Frankreich hat diese Grenze 2016 rechtlich geschützt; Deutschland setzt bisher auf betriebliche Vereinbarungen durch den Betriebsrat.","english":"The right to digital disconnection addresses a structural dissolution of boundaries: when communication devices are permanently available and employers expect to be reachable, the boundary between working time and free time blurs — with consequences for recovery, health, and family life. France legally protected this boundary in 2016; Germany so far relies on company-level agreements through the works council."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss remote work, algorithmic management, and the right to digital disconnection at B2."}}',
'{"items":[{"word":"das algorithmische Management","translation":"algorithmic management","pronunciation":"dahs al-go-RIT-mish-eh ma-na-shment","example":"Algorithmisches Management einsetzen."},{"word":"die Überwachung","translation":"monitoring/surveillance","pronunciation":"dee ü-ber-VA-khoong","example":"Digitale Überwachung."},{"word":"verschwimmen","translation":"to blur","pronunciation":"fer-SHVIM-en","example":"Grenzen verschwimmen."},{"word":"die Grenzauflösung","translation":"dissolution of boundaries","pronunciation":"dee GRENTS-owf-lö-zoong","example":"Strukturelle Grenzauflösung."},{"word":"intensivieren","translation":"to intensify","pronunciation":"in-ten-si-VEE-ren","example":"Widerspruch intensivieren."},{"word":"die Flexibilität","translation":"flexibility","pronunciation":"dee flex-i-bi-li-TÄT","example":"Räumliche Flexibilität."}]}',
'{"title":"Einerseits...andererseits — on the one hand...on the other hand","pattern":"einerseits X; andererseits Y = on the one hand X; on the other hand Y (einerseits = on one side/hand; andererseits = on the other side/hand — classic two-sided tension structure in analytical German)","explanation":"Einerseits = on the one hand (einer Seite = of one side). Andererseits = on the other hand (anderer Seite = of the other side). The structure presents two genuine tensions — not one right and one wrong, but two real dimensions in tension. Einerseits ermöglicht Remote-Arbeit Flexibilität; andererseits ermöglicht Digitalisierung tiefere Überwachung = on the one hand, remote work enables flexibility; on the other hand, digitalisation enables deeper surveillance. The pattern is the core move of balanced academic analysis — presenting a genuine dialectical tension. Compare: zum einen...zum anderen (on the one hand...on the other hand — slightly more formal); auf der einen Seite...auf der anderen (on one side...on the other — more spatial); zwar X, aber Y (granted X, but Y — more concessive).","examples":[{"sentence":"Einerseits erhöht Automatisierung die Effizienz; andererseits vernichtet sie Arbeitsplätze.","translation":"On the one hand, automation increases efficiency; on the other hand, it destroys jobs."},{"sentence":"Einerseits stärkt globaler Handel den Wohlstand; andererseits vertieft er Ungleichheiten.","translation":"On the one hand, global trade strengthens prosperity; on the other hand, it deepens inequalities."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Verschwimmen'' means?","options":["to blur","to dissolve","to fade","to merge"],"correctAnswer":"to blur"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The digitalisation of the world of work generates a paradox of control: on the one hand, remote work enables spatial and temporal flexibility that increases autonomy; on the other hand, digital infrastructure enables permanent monitoring of productivity, presence, and communication, which allows deeper control than the open-plan office gaze of the supervisor. Algorithmic management — the steering of work by software systems — intensifies this contradiction.","options":["Die Digitalisierung der Arbeitswelt erzeugt ein Paradox der Kontrolle: Einerseits ermöglicht Remote-Arbeit räumliche und zeitliche Flexibilität, die Autonomie steigert; andererseits ermöglicht digitale Infrastruktur eine permanente Überwachung von Produktivität, Anwesenheit und Kommunikation, die tiefere Kontrolle erlaubt als der Großraumbüro-Blick des Vorgesetzten. Algorithmisches Management — die Steuerung von Arbeit durch Software-Systeme — intensiviert diesen Widerspruch.","Remote-Arbeit gibt Autonomie, aber digitale Tools können Mitarbeiter überwachen.","Digitale Arbeit ist flexibler, aber auch kontrollierbarer als klassische Büroarbeit.","Algorithmisches Management ist die neue Form der Arbeitskontrolle im digitalen Zeitalter."],"correctAnswer":"Die Digitalisierung der Arbeitswelt erzeugt ein Paradox der Kontrolle: Einerseits ermöglicht Remote-Arbeit räumliche und zeitliche Flexibilität, die Autonomie steigert; andererseits ermöglicht digitale Infrastruktur eine permanente Überwachung von Produktivität, Anwesenheit und Kommunikation, die tiefere Kontrolle erlaubt als der Großraumbüro-Blick des Vorgesetzten. Algorithmisches Management — die Steuerung von Arbeit durch Software-Systeme — intensiviert diesen Widerspruch."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Einerseits erhöht Automatisierung die Effizienz; andererseits vernichtet sie ___.","options":["Arbeitsplätze","Jobs","Stellen","Arbeit"],"correctAnswer":"Arbeitsplätze"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: On the one hand global trade strengthens prosperity on the other hand it deepens inequalities","wordBankItems":["Einerseits","stärkt","globaler","Handel","den","Wohlstand",";","andererseits","vertieft","er","Ungleichheiten","."],"correctAnswer":"Einerseits stärkt globaler Handel den Wohlstand ; andererseits vertieft er Ungleichheiten ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Intensivieren'' means?","options":["to intensify","to increase","to amplify","to strengthen"],"correctAnswer":"to intensify"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000030f',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the platform economy at B2","Use Plattformökonomie vocabulary","Talk about Uber, Airbnb, Amazon, and the gig economy in Germany"],"explanation":{"intro":"Platform economy vocabulary covers gig work, platform capitalism, and Germany''s regulation debates at B2.","culturalNote":"Plattformökonomie: Key platforms: Uber (Personenbeförderung — banned/limited in Germany — PBefG/taxi law battles). Airbnb (Kurzzeitvermietung — Berlin, Munich: Zweckentfremdungsverbote — banned short-term rental to preserve housing). Amazon Marketplace. Delivery: Lieferando, Deliveroo. Task platforms: Upwork, Fiverr, Mechanical Turk. Key concept: Network effects (Netzwerkeffekte) — winner-takes-all dynamics. Data as capital (Datenmacht). Platform capitalism (Plattformkapitalismus — Nick Srnicek). Gig economy (Gig-Ökonomie — Clickworker — precarious). Key Germany: Scheinselbständigkeit (bogus self-employment — Crowdworker as employee or self-employed?). BAG ruling 2020: depends on economic dependency. EU Platform Work Directive 2024: presumption of employment. Antitrust: Bundeskartellamt (Federal Cartel Office) action against Google, Amazon. DMA (Digital Markets Act). Key tension: innovation vs. labour rights vs. market competition."},"examples":[{"german":"Die Plattformökonomie verändert die Machtstrukturen in der Arbeitswelt fundamental: Statt Arbeitsverhältnisse werden Auftragsverhältnisse konstruiert — Gig-Worker sind formal Selbständige, tragen das unternehmerische Risiko, haben aber keine Preissetzungsmacht, keine Verhandlungsposition und kein Kündigungsschutz. Diese rechtliche Umdeutung von Arbeitnehmenden in Selbständige externalisiert Kosten des Unternehmens auf Arbeitende und gesellschaftliche Sicherungssysteme.","english":"The platform economy fundamentally changes the power structures in the world of work: instead of employment relationships, commission relationships are constructed — gig workers are formally self-employed, bear the entrepreneurial risk, but have no pricing power, no bargaining position, and no protection against dismissal. This legal reinterpretation of employees as self-employed externalises the company''s costs onto workers and social security systems."},{"german":"Netzwerkeffekte erzeugen eine strukturelle Tendenz zur Monopolisierung in der Plattformökonomie: Der Wert einer Plattform steigt überproportional mit jedem neuen Nutzer — was First-Mover-Vorteile erzeugt, den Markt für Konkurrenten schließt und Regulierung herausfordert. Das Bundeskartellamt und die EU haben mit dem Digital Markets Act begonnen, diesem winner-takes-all-Mechanismus wettbewerbsrechtliche Grenzen zu setzen.","english":"Network effects generate a structural tendency toward monopolisation in the platform economy: the value of a platform rises more than proportionally with every new user — which creates first-mover advantages, closes the market for competitors, and challenges regulation. The Federal Cartel Office and the EU have begun, with the Digital Markets Act, to set competition law limits on this winner-takes-all mechanism."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss gig work, network effects, and platform regulation debates at B2."}}',
'{"items":[{"word":"das Auftragsverhältnis","translation":"commission relationship","pronunciation":"dahs OWF-traks-fer-hält-nis","example":"Auftragsverhältnis statt Arbeitsverhältnis."},{"word":"externalisieren","translation":"to externalise","pronunciation":"ex-ter-na-li-ZEE-ren","example":"Kosten externalisieren."},{"word":"die Preissetzungsmacht","translation":"pricing power","pronunciation":"dee PRYS-zet-soongs-makht","example":"Keine Preissetzungsmacht."},{"word":"überproportional","translation":"more than proportionally","pronunciation":"ü-ber-pro-por-tsyo-NAHL","example":"Überproportional steigen."},{"word":"der Netzwerkeffekt","translation":"network effect","pronunciation":"dayr NETS-verk-ef-ekt","example":"Netzwerkeffekte nutzen."},{"word":"die Monopolisierung","translation":"monopolisation","pronunciation":"dee mo-no-po-li-ZEE-roong","example":"Tendenz zur Monopolisierung."}]}',
'{"title":"Statt X werden Y konstruiert — instead of X, Y is constructed","pattern":"statt X werden Y konstruiert = instead of X, Y is constructed (statt + genitive/nominative = instead of; konstruieren = to construct, engineer — marks that something is artificially designed to avoid a more natural or legally expected form)","explanation":"Statt = instead of (introduces what is displaced). Konstruieren = to construct, design, engineer (not naturally arising — deliberately built). Werden Y konstruiert = Y is (passively) constructed. Statt Arbeitsverhältnisse werden Auftragsverhältnisse konstruiert = instead of employment relationships, commission relationships are constructed. Marks legal/structural engineering: deliberately building alternative structures to avoid rights, obligations, or costs that would attach to the natural form. Compare: durch X ersetzen (to replace with X — more neutral), X vermeiden durch Y (to avoid X through Y — more strategic), an Stelle von X (in place of X — more replacement), durch X umgehen (to circumvent X — similar intent, more evasive framing).","examples":[{"sentence":"Statt dauerhafter Arbeitsplätze werden befristete Verträge konstruiert.","translation":"Instead of permanent jobs, fixed-term contracts are constructed."},{"sentence":"Statt Mitarbeitern werden Franchisepartner konstruiert, um Sozialleistungen zu umgehen.","translation":"Instead of employees, franchise partners are constructed to circumvent social benefits."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Externalisieren'' means?","options":["to externalise","to outsource","to transfer","to offload"],"correctAnswer":"to externalise"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The platform economy fundamentally changes the power structures in the world of work: instead of employment relationships, commission relationships are constructed — gig workers are formally self-employed, bear the entrepreneurial risk, but have no pricing power, no bargaining position, and no protection against dismissal. This legal reinterpretation of employees as self-employed externalises the company''s costs onto workers and social security systems.","options":["Die Plattformökonomie verändert die Machtstrukturen in der Arbeitswelt fundamental: Statt Arbeitsverhältnisse werden Auftragsverhältnisse konstruiert — Gig-Worker sind formal Selbständige, tragen das unternehmerische Risiko, haben aber keine Preissetzungsmacht, keine Verhandlungsposition und kein Kündigungsschutz. Diese rechtliche Umdeutung von Arbeitnehmenden in Selbständige externalisiert Kosten des Unternehmens auf Arbeitende und gesellschaftliche Sicherungssysteme.","Gig-Worker sind formal selbständig, aber von der Plattform abhängig und schlecht abgesichert.","Plattformen nennen ihre Arbeiter Selbständige, um Sozialleistungen zu sparen.","Statt Jobs bieten Plattformen Aufträge — das schiebt das Risiko auf die Arbeitenden."],"correctAnswer":"Die Plattformökonomie verändert die Machtstrukturen in der Arbeitswelt fundamental: Statt Arbeitsverhältnisse werden Auftragsverhältnisse konstruiert — Gig-Worker sind formal Selbständige, tragen das unternehmerische Risiko, haben aber keine Preissetzungsmacht, keine Verhandlungsposition und kein Kündigungsschutz. Diese rechtliche Umdeutung von Arbeitnehmenden in Selbständige externalisiert Kosten des Unternehmens auf Arbeitende und gesellschaftliche Sicherungssysteme."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Statt dauerhafter Arbeitsplätze werden befristete Verträge ___.","options":["konstruiert","genutzt","eingesetzt","geschaffen"],"correctAnswer":"konstruiert"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Instead of employees franchise partners are constructed to circumvent social benefits","wordBankItems":["Statt","Mitarbeitern","werden","Franchisepartner","konstruiert",",","um","Sozialleistungen","zu","umgehen","."],"correctAnswer":"Statt Mitarbeitern werden Franchisepartner konstruiert , um Sozialleistungen zu umgehen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Überproportional'' means?","options":["more than proportionally","disproportionately","excessively","over-proportionally"],"correctAnswer":"more than proportionally"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000310',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss trade unions and collective bargaining at B2","Use Gewerkschaften und Tarifautonomie vocabulary","Talk about Germany''s co-determination, collective bargaining, and union decline"],"explanation":{"intro":"Trade unions and collective bargaining vocabulary covers Germany''s Tarifautonomie, Betriebsrat, and declining union membership at B2.","culturalNote":"Gewerkschaften und Tarifautonomie: Germany: Tarifautonomie (collective bargaining autonomy — Art. 9 GG — fundamental right — employer and union negotiate without state interference). DGB (Deutscher Gewerkschaftsbund — 8 member unions — IG Metall, ver.di, IG BCE — 5.8M members 2023 — declining). Tarifbindung (collective agreement coverage — 50% of employees — declining from 80% in 1990). IG Metall (2.1M — largest in the world — autoworkers, metalworkers). Mitbestimmung (co-determination — Betriebsrat = works council for workplace issues; Aufsichtsrat = supervisory board — 50% worker representatives in large companies). Key: Arbeitskampf (industrial action — Streik vs. Lockout). Mindestlohn (minimum wage — substitute for declining Tarifbindung). Allgemeinverbindlichkeitserklärung (extending collective agreements to non-union members). Key challenge: platform workers, self-employed, migrant workers — hard to organise."},"examples":[{"german":"Die Tarifautonomie ist das institutionelle Herzstück des deutschen Sozialpartnerschaftsmodells: Statt staatlicher Lohnfestsetzung regulieren Gewerkschaften und Arbeitgeberverbände Arbeitsbedingungen autonom durch Tarifverhandlungen — ein System, das auf kollektiver Gegenmacht basiert und voraussetzt, dass beide Seiten ausreichend organisiert sind, um Verhandlungsmacht zu haben. Sinkende Tarifbindung untergräbt diese Logik.","english":"Collective bargaining autonomy is the institutional heart of the German social partnership model: instead of state wage-setting, trade unions and employer associations autonomously regulate working conditions through collective negotiations — a system that is based on collective counter-power and presupposes that both sides are sufficiently organised to have bargaining power. Declining collective agreement coverage undermines this logic."},{"german":"Mitbestimmung in Deutschland geht über betriebliche Mitbestimmung hinaus: Das Montanmitbestimmungsgesetz (1951) und das Mitbestimmungsgesetz (1976) haben Arbeitnehmervertretung auch in den Aufsichtsräten großer Unternehmen verankert — eine institutionelle Innovation, die Kapital und Arbeit in der Unternehmensführung integriert und langfristige, auf Stabilität ausgerichtete Unternehmensstrategien begünstigt.","english":"Co-determination in Germany goes beyond company-level participation: the Montan Co-Determination Act (1951) and the Co-Determination Act (1976) have anchored worker representation also in the supervisory boards of large companies — an institutional innovation that integrates capital and labour in company management and favours long-term, stability-oriented corporate strategies."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Tarifautonomie, co-determination, and the German social partnership model at B2."}}',
'{"items":[{"word":"die Tarifautonomie","translation":"collective bargaining autonomy","pronunciation":"dee ta-REEF-ow-to-no-MEE","example":"Tarifautonomie schützen."},{"word":"die Gegenmacht","translation":"counter-power","pronunciation":"dee GEH-gen-makht","example":"Kollektive Gegenmacht."},{"word":"die Tarifbindung","translation":"collective agreement coverage","pronunciation":"dee ta-REEF-bin-doong","example":"Sinkende Tarifbindung."},{"word":"verankern","translation":"to anchor/enshrine","pronunciation":"fer-AN-kern","example":"Rechte verankern."},{"word":"die Unternehmensführung","translation":"company management","pronunciation":"dee oon-ter-NEH-mens-fü-roong","example":"In der Unternehmensführung."},{"word":"begünstigen","translation":"to favour","pronunciation":"beh-GÜN-sti-gen","example":"Strategien begünstigen."}]}',
'{"title":"X setzt voraus, dass Y — X presupposes that Y (sentence form)","pattern":"X setzt voraus, dass Y = X presupposes that Y (full sentence presupposition — voraussetzen dass = presuppose that — like the noun-form pattern but with a full clause as the precondition)","explanation":"Voraussetzen + dass-clause = to presuppose that (full sentence form). X setzt voraus, dass Y = X presupposes that Y (Y is the condition, full sentence). Das System setzt voraus, dass beide Seiten ausreichend organisiert sind = the system presupposes that both sides are sufficiently organised. Compare: erfordern, dass (to require that — more actionable demand); implizieren, dass (to imply that — weaker, inferential); bedingen, dass (to entail that — more causal); nur funktionieren, wenn (only work if — conditional rather than presuppositional — marks failure when condition is not met).","examples":[{"sentence":"Demokratie setzt voraus, dass Bürger informiert und engagiert sind.","translation":"Democracy presupposes that citizens are informed and engaged."},{"sentence":"Das Modell setzt voraus, dass Märkte effizient sind.","translation":"The model presupposes that markets are efficient."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Gegenmacht'' means?","options":["counter-power","opposing force","countervailing power","resistance"],"correctAnswer":"counter-power"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Collective bargaining autonomy is the institutional heart of the German social partnership model: instead of state wage-setting, trade unions and employer associations autonomously regulate working conditions through collective negotiations — a system that is based on collective counter-power and presupposes that both sides are sufficiently organised to have bargaining power. Declining collective agreement coverage undermines this logic.","options":["Die Tarifautonomie ist das institutionelle Herzstück des deutschen Sozialpartnerschaftsmodells: Statt staatlicher Lohnfestsetzung regulieren Gewerkschaften und Arbeitgeberverbände Arbeitsbedingungen autonom durch Tarifverhandlungen — ein System, das auf kollektiver Gegenmacht basiert und voraussetzt, dass beide Seiten ausreichend organisiert sind, um Verhandlungsmacht zu haben. Sinkende Tarifbindung untergräbt diese Logik.","Gewerkschaften und Arbeitgeber handeln Löhne ohne staatliche Einmischung aus.","Tarifautonomie funktioniert nur, wenn beide Seiten stark genug sind.","Sinkende Gewerkschaftsmitgliedschaft schwächt das Lohnverhandlungssystem."],"correctAnswer":"Die Tarifautonomie ist das institutionelle Herzstück des deutschen Sozialpartnerschaftsmodells: Statt staatlicher Lohnfestsetzung regulieren Gewerkschaften und Arbeitgeberverbände Arbeitsbedingungen autonom durch Tarifverhandlungen — ein System, das auf kollektiver Gegenmacht basiert und voraussetzt, dass beide Seiten ausreichend organisiert sind, um Verhandlungsmacht zu haben. Sinkende Tarifbindung untergräbt diese Logik."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Modell setzt voraus, dass Märkte effizient ___.","options":["sind","sein","werden","seien"],"correctAnswer":"sind"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Democracy presupposes that citizens are informed and engaged","wordBankItems":["Demokratie","setzt","voraus",",","dass","Bürger","informiert","und","engagiert","sind","."],"correctAnswer":"Demokratie setzt voraus , dass Bürger informiert und engagiert sind ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Verankern'' means?","options":["to anchor/enshrine","to embed","to establish","to fix"],"correctAnswer":"to anchor/enshrine"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000311',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss immigration and work at B2","Use Einwanderung und Arbeit vocabulary","Talk about Germany''s Fachkräftemangel, immigration law, and integration in the workplace"],"explanation":{"intro":"Immigration and work vocabulary covers Germany''s skilled labour shortage, immigration law reforms, and workplace integration at B2.","culturalNote":"Einwanderung und Arbeit: Germany: Fachkräftemangel (skilled labour shortage — 2 million vacancies in 2023 — key sectors: Pflege, IT, Handwerk, Medizin). Fachkräfteeinwanderungsgesetz (2020 — Skilled Immigration Act — extended 2023 — points-based elements, Chancenkarte). Key: EU freedom of movement (Eastern Europe). Non-EU immigration: third-country nationals — complex procedures. Blue Card EU (for highly qualified non-EU workers). Migrationsabkommen (migration agreements — Germany-Morocco, Germany-Kenya 2023). Anerkennungsrecht (recognition of foreign qualifications — still problematic). Sprachvoraussetzungen (language requirements — German B1 level for integration). Sprachkurs (integration course — 600h language + orientation). Arbeitsmarktintegration von Geflüchteten (refugees — only 20% in employment after 3 years). Key tension: Willkommenskultur (welcome culture) vs. Überforderung (overwhelm) at local level. Brain drain vs. Brain gain. Remittances. Transnationalism."},"examples":[{"german":"Deutschlands Reaktion auf den Fachkräftemangel ist ein Paradigmenwechsel in der Einwanderungspolitik: Nach Jahrzehnten, in denen Deutschland kein Einwanderungsland sein wollte, hat es sich zu einem aktiven Anwerbeland transformiert — mit Fachkräfteeinwanderungsgesetz, Chancenkarte und Migrationsabkommen. Dieser Wandel ist nicht nur pragmatisch-ökonomisch, sondern auch kulturell und gesellschaftlich bedeutsam: Er setzt voraus, dass Deutschland seine Identität als Einwanderungsgesellschaft annimmt.","english":"Germany''s response to the skilled labour shortage is a paradigm shift in immigration policy: after decades in which Germany did not want to be a country of immigration, it has transformed into an active recruitment country — with a skilled immigration law, opportunity card, and migration agreements. This change is not only pragmatically economic, but also culturally and socially significant: it presupposes that Germany accepts its identity as an immigration society."},{"german":"Die Anerkennung ausländischer Berufsabschlüsse bleibt ein strukturelles Hemmnis der Arbeitsmarktintegration: Selbst wenn Fachkräfte aus dem Ausland rechtlich einreisen können, verhindert ein fragmentiertes und bürokratisches Anerkennungsverfahren die rasche Integration in den Beruf. Für reglementierte Berufe — Ärzte, Pflegepersonal, Ingenieure — sind Nachqualifizierungen, Sprachprüfungen und Wartezeiten die Regel, nicht die Ausnahme.","english":"The recognition of foreign professional qualifications remains a structural obstacle to labour market integration: even when skilled workers from abroad can legally enter, a fragmented and bureaucratic recognition process prevents rapid integration into the profession. For regulated professions — doctors, nursing staff, engineers — supplementary qualifications, language examinations, and waiting periods are the rule, not the exception."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s Fachkräfteeinwanderungsgesetz, qualification recognition, and the shift to an immigration country at B2."}}',
'{"items":[{"word":"das Hemmnis","translation":"obstacle/impediment","pronunciation":"dahs HEM-nis","example":"Strukturelles Hemmnis."},{"word":"fragmentiert","translation":"fragmented","pronunciation":"frag-men-TEERT","example":"Fragmentiertes Verfahren."},{"word":"der Paradigmenwechsel","translation":"paradigm shift","pronunciation":"dayr pa-ra-DIG-men-vek-sel","example":"Einwanderungspolitischer Paradigmenwechsel."},{"word":"annehmen","translation":"to accept/adopt","pronunciation":"AN-neh-men","example":"Identität annehmen."},{"word":"die Anwerbung","translation":"recruitment","pronunciation":"dee AN-ver-boong","example":"Aktive Anwerbung."},{"word":"reglementiert","translation":"regulated","pronunciation":"reh-gleh-men-TEERT","example":"Reglementierter Beruf."}]}',
'{"title":"X transformiert sich zu Y — X transforms into Y","pattern":"X transformiert sich zu Y = X transforms into Y (sich transformieren zu = to transform into — reflexive; marks a deep structural change in identity or nature, not just function)","explanation":"Sich transformieren = to transform (reflexive: the subject transforms itself). Zu Y = into Y (marks the new identity/form). X hat sich zu einem aktiven Anwerbeland transformiert = X has transformed into an active recruitment country. Marks a deep structural identity change — not just doing something different (function change) but becoming something different (identity change). Compare: sich wandeln zu (to change into — softer, more gradual), sich entwickeln zu (to develop into — more evolutionary), sich verwandeln in (to turn into — more complete/dramatic), werden zu (to become — simpler, less marked as transformation).","examples":[{"sentence":"Die Organisation hat sich von einer nationalen zu einer globalen Institution transformiert.","translation":"The organisation has transformed from a national into a global institution."},{"sentence":"Die Stadt transformiert sich zu einem Technologiezentrum.","translation":"The city is transforming into a technology centre."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Hemmnis'' means?","options":["obstacle/impediment","barrier","blockage","constraint"],"correctAnswer":"obstacle/impediment"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Germany''s response to the skilled labour shortage is a paradigm shift in immigration policy: after decades in which Germany did not want to be a country of immigration, it has transformed into an active recruitment country — with a skilled immigration law, opportunity card, and migration agreements. This change is not only pragmatically economic, but also culturally and socially significant: it presupposes that Germany accepts its identity as an immigration society.","options":["Deutschlands Reaktion auf den Fachkräftemangel ist ein Paradigmenwechsel in der Einwanderungspolitik: Nach Jahrzehnten, in denen Deutschland kein Einwanderungsland sein wollte, hat es sich zu einem aktiven Anwerbeland transformiert — mit Fachkräfteeinwanderungsgesetz, Chancenkarte und Migrationsabkommen. Dieser Wandel ist nicht nur pragmatisch-ökonomisch, sondern auch kulturell und gesellschaftlich bedeutsam: Er setzt voraus, dass Deutschland seine Identität als Einwanderungsgesellschaft annimmt.","Deutschland wirbt aktiv um Fachkräfte aus dem Ausland, um den Mangel zu beheben.","Das Fachkräfteeinwanderungsgesetz ermöglicht Qualifizierten aus Drittstaaten die Einwanderung.","Deutschland will Einwanderungsland sein und richtet seine Politik darauf aus."],"correctAnswer":"Deutschlands Reaktion auf den Fachkräftemangel ist ein Paradigmenwechsel in der Einwanderungspolitik: Nach Jahrzehnten, in denen Deutschland kein Einwanderungsland sein wollte, hat es sich zu einem aktiven Anwerbeland transformiert — mit Fachkräfteeinwanderungsgesetz, Chancenkarte und Migrationsabkommen. Dieser Wandel ist nicht nur pragmatisch-ökonomisch, sondern auch kulturell und gesellschaftlich bedeutsam: Er setzt voraus, dass Deutschland seine Identität als Einwanderungsgesellschaft annimmt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Stadt transformiert sich zu einem ___.","options":["Technologiezentrum","Zentrum","Ort","Hub"],"correctAnswer":"Technologiezentrum"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The organisation has transformed from a national into a global institution","wordBankItems":["Die","Organisation","hat","sich","von","einer","nationalen","zu","einer","globalen","Institution","transformiert","."],"correctAnswer":"Die Organisation hat sich von einer nationalen zu einer globalen Institution transformiert ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Reglementiert'' means?","options":["regulated","restricted","controlled","governed"],"correctAnswer":"regulated"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000312',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss pension provision and policy at B2","Use Altersvorsorge und Rentenpolitik vocabulary","Talk about Germany''s three-pillar pension system, demographic challenge, and pension reform"],"explanation":{"intro":"Pension provision vocabulary covers Germany''s three-pillar system, demographic crisis, and pension reform debates at B2.","culturalNote":"Altersvorsorge und Rentenpolitik: Germany: Drei-Säulen-Modell (three-pillar model — 1. Gesetzliche Rentenversicherung = statutory pension — GRV; 2. Betriebliche Altersvorsorge = occupational pension; 3. Private Altersvorsorge = private provision — Riester-Rente, Rürup-Rente). Key: Generationenvertrag (generational contract — pay-as-you-go — workers today pay for current retirees). Demografische Herausforderung: 2035 Baby-Boomer retire — ratio workers:retirees worsens dramatically. Rentenniveau (pension level — 48% of average net wage — minimum — debate about 50% floor). Renteneintrittsalter (retirement age — 67 — debate over 70). Riester-Rente (private pension — 16M contracts — controversial: fees, complexity, low returns). Key reform: Aktienrente (equity pension — government equity fund — SPD-FDP plan 2023). Grundrente (basic pension — 2021 — for long-term low earners — controversial). Altersarmut (old-age poverty — growing — especially women — care work not counted)."},"examples":[{"german":"Der Generationenvertrag, auf dem das Umlageverfahren der gesetzlichen Rente basiert, steht unter demografischem Druck: Wenn weniger Erwerbstätige mehr Rentnerinnen und Rentner finanzieren müssen, gerät das Gleichgewicht zwischen Beitragssatz, Rentenniveau und Renteneintrittsalter aus dem Lot — ein Trilemma, bei dem eine Verbesserung in einer Dimension zwangsläufig Verschlechterungen in den anderen nach sich zieht.","english":"The generational contract on which the pay-as-you-go system of statutory pensions is based is under demographic pressure: when fewer employed persons must finance more pensioners, the balance between contribution rate, pension level, and retirement age goes out of kilter — a trilemma in which an improvement in one dimension inevitably entails deteriorations in the others."},{"german":"Altersarmut ist eine geschlechtsspezifische Erscheinung in Deutschland: Frauen haben aufgrund von Erwerbsunterbrechungen für Kindererziehung und Pflege sowie der Konzentration in Teilzeit und Niedriglohnbranchen durchschnittlich deutlich niedrigere Rentenanwartschaften als Männer — eine Ungleichheit, die die Lohnlücke über das Erwerbsleben hinaus in die Rentenphase verlängert und die gesellschaftliche Unterbewertung von Sorgearbeit institutionalisiert.","english":"Old-age poverty is a gender-specific phenomenon in Germany: women have significantly lower average pension entitlements than men due to interruptions in employment for childcare and caregiving and the concentration in part-time and low-wage industries — an inequality that extends the wage gap beyond working life into the pension phase and institutionalises the social undervaluation of care work."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s three-pillar pension system, the generational contract, and old-age poverty at B2."}}',
'{"items":[{"word":"das Umlageverfahren","translation":"pay-as-you-go system","pronunciation":"dahs OOM-lah-geh-fer-fah-ren","example":"Umlageverfahren der Rente."},{"word":"das Trilemma","translation":"trilemma","pronunciation":"dahs tri-LEM-ma","example":"Rentenpolitisches Trilemma."},{"word":"die Rentenanwartschaft","translation":"pension entitlement","pronunciation":"dee REN-ten-an-vart-shaf","example":"Niedrige Rentenanwartschaften."},{"word":"nach sich ziehen","translation":"to entail/bring about","pronunciation":"nakh zikh TSEE-en","example":"Verschlechterungen nach sich ziehen."},{"word":"institutionalisieren","translation":"to institutionalise","pronunciation":"in-sti-too-tsyo-na-li-ZEE-ren","example":"Ungleichheit institutionalisieren."},{"word":"das Rentenniveau","translation":"pension level","pronunciation":"dahs REN-ten-ni-voh","example":"Sinklendes Rentenniveau."}]}',
'{"title":"X zieht Y nach sich — X entails/brings Y in its wake","pattern":"X zieht Y nach sich = X entails Y, brings Y in its wake (nach sich ziehen = to bring in one''s wake, entail — separable-like idiom: zieht...nach sich; marks that X inevitably leads to Y as a consequence — stronger than führt zu)","explanation":"Nach sich ziehen = to bring in one''s wake, entail (nach = after; sich = oneself; ziehen = to pull — to pull after oneself). X zieht Y nach sich = X drags Y along as a consequence. Eine Verbesserung zieht Verschlechterungen nach sich = an improvement entails deteriorations. Marks a strong, often unavoidable causal link — X doesn''t just lead to Y, it pulls Y along as a necessary implication. Compare: führt zu Y (leads to Y — more neutral causal), impliziert Y (implies Y — more logical), bedingt Y (requires Y — more conditional), hat Y zur Folge (has Y as a consequence — more neutral result).","examples":[{"sentence":"Jede Steuersenkung zieht Ausgabenkürzungen nach sich.","translation":"Every tax cut entails spending cuts."},{"sentence":"Der Ausnahmezustand zieht eine Einschränkung der Grundrechte nach sich.","translation":"The state of emergency entails a restriction of fundamental rights."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Trilemma'' means?","options":["trilemma","three-way dilemma","triple constraint","three-sided conflict"],"correctAnswer":"trilemma"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The generational contract on which the pay-as-you-go system of statutory pensions is based is under demographic pressure: when fewer employed persons must finance more pensioners, the balance between contribution rate, pension level, and retirement age goes out of kilter — a trilemma in which an improvement in one dimension inevitably entails deteriorations in the others.","options":["Der Generationenvertrag, auf dem das Umlageverfahren der gesetzlichen Rente basiert, steht unter demografischem Druck: Wenn weniger Erwerbstätige mehr Rentnerinnen und Rentner finanzieren müssen, gerät das Gleichgewicht zwischen Beitragssatz, Rentenniveau und Renteneintrittsalter aus dem Lot — ein Trilemma, bei dem eine Verbesserung in einer Dimension zwangsläufig Verschlechterungen in den anderen nach sich zieht.","Das Rentensystem steht unter Druck, weil weniger Arbeitnehmer mehr Rentner finanzieren müssen.","Das Dreiecks-Dilemma der Rente: Man kann Beiträge, Niveau und Eintrittsalter nicht alle gleichzeitig verbessern.","Das Umlageverfahren ist durch den demografischen Wandel gefährdet."],"correctAnswer":"Der Generationenvertrag, auf dem das Umlageverfahren der gesetzlichen Rente basiert, steht unter demografischem Druck: Wenn weniger Erwerbstätige mehr Rentnerinnen und Rentner finanzieren müssen, gerät das Gleichgewicht zwischen Beitragssatz, Rentenniveau und Renteneintrittsalter aus dem Lot — ein Trilemma, bei dem eine Verbesserung in einer Dimension zwangsläufig Verschlechterungen in den anderen nach sich zieht."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Jede Steuersenkung zieht Ausgabenkürzungen nach ___.","options":["sich","ihm","dem","ihr"],"correctAnswer":"sich"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The state of emergency entails a restriction of fundamental rights","wordBankItems":["Der","Ausnahmezustand","zieht","eine","Einschränkung","der","Grundrechte","nach","sich","."],"correctAnswer":"Der Ausnahmezustand zieht eine Einschränkung der Grundrechte nach sich ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Institutionalisieren'' means?","options":["to institutionalise","to formalise","to embed","to establish"],"correctAnswer":"to institutionalise"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000313',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss social cohesion at B2","Use Sozialer Zusammenhalt vocabulary","Talk about Germany''s social cohesion, trust, and the polarisation debate"],"explanation":{"intro":"Social cohesion vocabulary covers social trust, polarisation, and Germany''s Bertelsmann Stiftung studies on cohesion at B2.","culturalNote":"Sozialer Zusammenhalt: Key research: Bertelsmann Stiftung (2019, 2022 Radar sozialer Zusammenhalt — social cohesion falling in Germany — especially since 2020). Robert Putnam (Bowling Alone — 2000 — decline of social capital in USA — echo in Germany). Ehrenamt (volunteering — 26M volunteers in Germany — key cohesion mechanism). Key indicators: trust (Vertrauen — interpersonal and institutional), solidarity (Solidarität), sense of belonging (Zugehörigkeitsgefühl). Soziale Spaltung (social division — rich-poor, east-west, urban-rural, old-new). Key: Corona as solidarity test — initial solidarity followed by polarisation (Querdenker). Populismus (populism — AFD — Vertrauensverlust in Institutionen). PEGIDA. Extremismus. Soziale Medien und Blasenbildung (social media and echo chambers). Key concept: Bonding capital (bridging) vs. Bridging capital (Robert Putnam). Integration and cohesion. Key challenge: migrant integration and cohesion. Einsamkeit (loneliness — epidemic — social cohesion at individual level)."},"examples":[{"german":"Sozialer Zusammenhalt ist mehr als die Abwesenheit von Konflikten — er bezeichnet die positive Bindungskraft einer Gesellschaft: das Vertrauen zwischen Bürgerinnen und Bürgern und gegenüber Institutionen, das Solidaritätsgefühl über soziale Gruppen hinweg, das Zugehörigkeitsgefühl zu einer gemeinsamen politischen Gemeinschaft. Eine Gesellschaft kann formal stabil sein und dennoch kohäsionsarm: wenn Polarisierung, Misstrauen und Parallelgesellschaften die gemeinsamen Grundlagen erodieren.","english":"Social cohesion is more than the absence of conflicts — it designates the positive binding force of a society: the trust between citizens and towards institutions, the feeling of solidarity across social groups, the sense of belonging to a shared political community. A society can be formally stable and yet cohesion-poor: when polarisation, mistrust, and parallel societies erode the common foundations."},{"german":"Robert Putnam hat zwischen bonding und bridging social capital unterschieden, um verschiedene Arten sozialer Bindung zu beschreiben: Bonding capital stärkt Bindungen innerhalb von Gruppen — Familie, Nachbarschaft, Gemeinde — und erzeugt Solidarität, kann aber Außenseiter ausschließen. Bridging capital verbindet verschiedene soziale Gruppen und ist für gesellschaftlichen Zusammenhalt in pluralistischen, heterogenen Gesellschaften entscheidend.","english":"Robert Putnam distinguished between bonding and bridging social capital to describe different types of social bonds: bonding capital strengthens ties within groups — family, neighbourhood, community — and generates solidarity, but can exclude outsiders. Bridging capital connects different social groups and is decisive for social cohesion in pluralistic, heterogeneous societies."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss social cohesion, Putnam''s bonding/bridging capital, and polarisation in Germany at B2."}}',
'{"items":[{"word":"die Bindungskraft","translation":"binding force","pronunciation":"dee BIN-doongs-kraft","example":"Soziale Bindungskraft."},{"word":"das Zugehörigkeitsgefühl","translation":"sense of belonging","pronunciation":"dahs tsoo-geh-HÖ-rikh-kyts-geh-fühl","example":"Zugehörigkeitsgefühl stärken."},{"word":"kohäsionsarm","translation":"cohesion-poor","pronunciation":"ko-HÄ-zyohns-arm","example":"Kohäsionsarme Gesellschaft."},{"word":"erodieren","translation":"to erode","pronunciation":"eh-ro-DEE-ren","example":"Grundlagen erodieren."},{"word":"das Misstrauen","translation":"mistrust","pronunciation":"dahs MIS-trow-en","example":"Institutionelles Misstrauen."},{"word":"bridging capital","translation":"bridging capital","pronunciation":"BRID-zhing KA-pi-tal","example":"Bridging capital aufbauen."}]}',
'{"title":"X ist mehr als die Abwesenheit von Y — X is more than the absence of Y","pattern":"X ist mehr als die Abwesenheit von Y = X is more than the absence of Y (Abwesenheit = absence — marks that the positive definition of X is richer than the mere negation of Y; positively defines rather than negatively)","explanation":"Abwesenheit = absence (ab = away from + Wesen = being — the state of not being there). Mehr als die Abwesenheit von Y = more than the absence of Y (the mere lack of Y is not enough to define X). Sozialer Zusammenhalt ist mehr als die Abwesenheit von Konflikten = social cohesion is more than the absence of conflicts. The pattern pushes toward positive definition: X isn''t just ''not Y'' but has positive content (trust, solidarity, belonging). Closely related to ''umfasst mehr als'' — but focused specifically on the absence/negation move. Compare: nicht bloß das Fehlen von Y (not merely the absence of Y — less elegant), im positiven Sinne (in the positive sense), darüber hinaus (beyond that — less structural).","examples":[{"sentence":"Frieden ist mehr als die Abwesenheit von Krieg.","translation":"Peace is more than the absence of war."},{"sentence":"Inklusion ist mehr als die Abwesenheit von Diskriminierung.","translation":"Inclusion is more than the absence of discrimination."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Erodieren'' means?","options":["to erode","to decay","to crumble","to corrode"],"correctAnswer":"to erode"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Social cohesion is more than the absence of conflicts — it designates the positive binding force of a society: the trust between citizens and towards institutions, the feeling of solidarity across social groups, the sense of belonging to a shared political community. A society can be formally stable and yet cohesion-poor: when polarisation, mistrust, and parallel societies erode the common foundations.","options":["Sozialer Zusammenhalt ist mehr als die Abwesenheit von Konflikten — er bezeichnet die positive Bindungskraft einer Gesellschaft: das Vertrauen zwischen Bürgerinnen und Bürgern und gegenüber Institutionen, das Solidaritätsgefühl über soziale Gruppen hinweg, das Zugehörigkeitsgefühl zu einer gemeinsamen politischen Gemeinschaft. Eine Gesellschaft kann formal stabil sein und dennoch kohäsionsarm: wenn Polarisierung, Misstrauen und Parallelgesellschaften die gemeinsamen Grundlagen erodieren.","Sozialer Zusammenhalt bedeutet, dass Menschen einander vertrauen und solidarisch sind.","Eine Gesellschaft ohne Konflikte ist nicht unbedingt kohäsiv — es kommt auf Vertrauen an.","Polarisierung und Misstrauen zerstören sozialen Zusammenhalt auch ohne offene Konflikte."],"correctAnswer":"Sozialer Zusammenhalt ist mehr als die Abwesenheit von Konflikten — er bezeichnet die positive Bindungskraft einer Gesellschaft: das Vertrauen zwischen Bürgerinnen und Bürgern und gegenüber Institutionen, das Solidaritätsgefühl über soziale Gruppen hinweg, das Zugehörigkeitsgefühl zu einer gemeinsamen politischen Gemeinschaft. Eine Gesellschaft kann formal stabil sein und dennoch kohäsionsarm: wenn Polarisierung, Misstrauen und Parallelgesellschaften die gemeinsamen Grundlagen erodieren."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Frieden ist mehr als die Abwesenheit von ___.","options":["Krieg","Konflikten","Gewalt","Auseinandersetzungen"],"correctAnswer":"Krieg"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Inclusion is more than the absence of discrimination","wordBankItems":["Inklusion","ist","mehr","als","die","Abwesenheit","von","Diskriminierung","."],"correctAnswer":"Inklusion ist mehr als die Abwesenheit von Diskriminierung ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Misstrauen'' means?","options":["mistrust","distrust","suspicion","doubt"],"correctAnswer":"mistrust"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000314',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss cultural policy and funding at B2","Use Kulturpolitik und Kulturförderung vocabulary","Talk about Germany''s Kulturstaat, arts funding, and the Kulturinfarkt debate"],"explanation":{"intro":"Cultural policy vocabulary covers Germany''s Kulturstaat, arts subsidies, and debates about funding at B2.","culturalNote":"Kulturpolitik und Kulturförderung: Germany: Kulturstaat (cultural state — Art. 35 Einigungsvertrag — cultural landscape is part of German identity). Germany has the world''s densest publicly funded cultural infrastructure: 83 opera houses (more than all of North America), 700+ professional orchestras, 5000+ museums, 1000+ theatre companies. Budget: €13.8bn/year public cultural spending. Key: Kulturförderalismus (cultural federalism — Länder responsibility). BKM (Beauftragte der Bundesregierung für Kultur und Medien — Federal Commissioner for Culture). Goethe-Institut (international cultural diplomacy). Kontroverse: Kulturinfarkt (2012 book — too much public arts funding → mediocrity). Key debate: Zugänglichkeit (accessibility — is public funding for opera elitist?). Kunstfreiheit (artistic freedom — Art. 5 GG). Populärkultur vs. Hochkultur. Erinnerungskultur (culture of remembrance — Holocaust memorials, Stolpersteine). Kulturelles Erbe (cultural heritage — UNESCO). Buchpreisbindung (book price maintenance — protects bookshops)."},"examples":[{"german":"Deutschlands öffentliche Kulturförderung basiert auf der Prämisse, dass Kultur Marktversagen unterliegt: Da kulturelle Güter externe Effekte erzeugen — Identitätsstiftung, gesellschaftliche Kohäsion, Wissensweitergabe über Generationen — und kommerziell nicht profitabel sein müssen, ist staatliche Subvention gerechtfertigt. Diese Logik schützt künstlerische Experimente, nischige Genres und regionale Identitäten, die der Markt nicht nachfragt.","english":"Germany''s public cultural funding is based on the premise that culture is subject to market failure: since cultural goods generate external effects — identity formation, social cohesion, transmission of knowledge across generations — and do not have to be commercially profitable, public subsidy is justified. This logic protects artistic experiments, niche genres, and regional identities that the market does not demand."},{"german":"Die Erinnerungskultur ist eine Besonderheit der deutschen Kulturpolitik: Die gesellschaftliche Auseinandersetzung mit NS-Vergangenheit, Holocaust und Kriegsverbrechen ist institutionell verankert — durch Gedenkstätten, Bildungsarbeit, Stolpersteine, Mahnmale und gesetzliche Verbote von Holocaustleugnung — und bildet eine normative Grundlage der demokratischen Identität der Bundesrepublik.","english":"The culture of remembrance is a particularity of German cultural policy: the societal confrontation with the Nazi past, the Holocaust, and war crimes is institutionally anchored — through memorials, educational work, Stolpersteine, monuments, and legal prohibitions on Holocaust denial — and forms a normative foundation of the democratic identity of the Federal Republic."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s Kulturstaat, arts funding rationale, and Erinnerungskultur at B2."}}',
'{"items":[{"word":"die Prämisse","translation":"premise","pronunciation":"dee PRÄ-mi-seh","example":"Auf einer Prämisse basieren."},{"word":"das Marktversagen","translation":"market failure","pronunciation":"dahs MARKT-fer-zah-gen","example":"Kulturelles Marktversagen."},{"word":"die Identitätsstiftung","translation":"identity formation","pronunciation":"dee i-den-ti-TÄTS-shtif-toong","example":"Kulturelle Identitätsstiftung."},{"word":"nischig","translation":"niche","pronunciation":"NI-shikh","example":"Nischige Genres."},{"word":"institutionell","translation":"institutionally","pronunciation":"in-sti-too-tsyo-NEL","example":"Institutionell verankert."},{"word":"die Gedenkstätte","translation":"memorial","pronunciation":"dee geh-DENK-shtet-eh","example":"Gedenkstätten besuchen."}]}',
'{"title":"X basiert auf der Prämisse, dass Y — X is based on the premise that Y","pattern":"X basiert auf der Prämisse, dass Y = X is based on the premise that Y (basieren auf + Prämisse, dass = to be based on the premise that — marks the foundational assumption that justifies X — revealing the hidden normative or analytical starting point)","explanation":"Basieren auf = to be based on (Basis = base; basieren auf + dative = to rest on). Prämisse = premise (logical starting assumption that doesn''t need to be justified within the argument — it is the foundation). X basiert auf der Prämisse, dass Y = X is based on the premise that Y (Y is the foundational assumption, not a conclusion). The pattern makes implicit premises explicit — revealing the normative or empirical starting point. Compare: setzt X voraus (presupposes X — more logical precondition), X beruht auf der Annahme (is based on the assumption — similar, less technical), X nimmt an, dass (assumes that — less formal), X geht von X aus (proceeds from X — more movement-oriented).","examples":[{"sentence":"Die Wirtschaftspolitik basiert auf der Prämisse, dass Wachstum Wohlstand erzeugt.","translation":"Economic policy is based on the premise that growth generates prosperity."},{"sentence":"Das Bildungssystem basiert auf der Prämisse, dass Chancengleichheit durch formale Gleichbehandlung erreicht wird.","translation":"The education system is based on the premise that equal opportunity is achieved through formal equal treatment."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Marktversagen'' means?","options":["market failure","market gap","market deficit","market flaw"],"correctAnswer":"market failure"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Germany''s public cultural funding is based on the premise that culture is subject to market failure: since cultural goods generate external effects — identity formation, social cohesion, transmission of knowledge across generations — and do not have to be commercially profitable, public subsidy is justified. This logic protects artistic experiments, niche genres, and regional identities that the market does not demand.","options":["Deutschlands öffentliche Kulturförderung basiert auf der Prämisse, dass Kultur Marktversagen unterliegt: Da kulturelle Güter externe Effekte erzeugen — Identitätsstiftung, gesellschaftliche Kohäsion, Wissensweitergabe über Generationen — und kommerziell nicht profitabel sein müssen, ist staatliche Subvention gerechtfertigt. Diese Logik schützt künstlerische Experimente, nischige Genres und regionale Identitäten, die der Markt nicht nachfragt.","Deutschland fördert Kultur öffentlich, weil Kunst nicht immer kommerziell sein kann.","Oper und Theater wären ohne staatliche Förderung nicht überlebensfähig.","Kulturelle Identität braucht Schutz durch den Staat, der Markt kann das nicht leisten."],"correctAnswer":"Deutschlands öffentliche Kulturförderung basiert auf der Prämisse, dass Kultur Marktversagen unterliegt: Da kulturelle Güter externe Effekte erzeugen — Identitätsstiftung, gesellschaftliche Kohäsion, Wissensweitergabe über Generationen — und kommerziell nicht profitabel sein müssen, ist staatliche Subvention gerechtfertigt. Diese Logik schützt künstlerische Experimente, nischige Genres und regionale Identitäten, die der Markt nicht nachfragt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Wirtschaftspolitik basiert auf der Prämisse, dass Wachstum Wohlstand ___.","options":["erzeugt","schafft","bringt","sichert"],"correctAnswer":"erzeugt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The education system is based on the premise that equal opportunity is achieved through formal equal treatment","wordBankItems":["Das","Bildungssystem","basiert","auf","der","Prämisse",",","dass","Chancengleichheit","durch","formale","Gleichbehandlung","erreicht","wird","."],"correctAnswer":"Das Bildungssystem basiert auf der Prämisse , dass Chancengleichheit durch formale Gleichbehandlung erreicht wird ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Gedenkstätte'' means?","options":["memorial","monument","commemoration site","remembrance site"],"correctAnswer":"memorial"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000315',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss media policy and the public sphere at B2","Use Medienpolitik und Öffentlichkeit vocabulary","Talk about German public broadcasting, ARD/ZDF, press freedom, and media concentration"],"explanation":{"intro":"Media policy vocabulary covers Germany''s public broadcasting (ARD/ZDF), press freedom ranking, and the Öffentlichkeitstheorie at B2.","culturalNote":"Medienpolitik und Öffentlichkeit: Germany: Pressefreiheit (press freedom — Art. 5 GG — Reporters Without Borders: Germany #5 globally 2023). ARD/ZDF (public broadcasters — funded by Rundfunkbeitrag/broadcasting fee €18.36/month — 3rd largest public broadcasting system globally after BBC and NHK). Rundfunkstaatsvertrag (Broadcasting Treaty — interstate treaty, not federal law). Key: Meinungsfreiheit vs. Holocaustleugnung (speech restrictions — unique to Germany). Presserat (German Press Council — self-regulation). Lokalzeitungen (local newspapers — massive decline — Zeitungssterben). Key: Medienkonzentration (media concentration — Bertelsmann, Axel Springer, Funke Mediengruppe). Digital platforms — Meta, Google, TikTok — disrupting media economics. Habermas (Jürgen Habermas — Strukturwandel der Öffentlichkeit 1962 — public sphere theory — deliberative democracy). Filterblasen (filter bubbles). Desinformation."},"examples":[{"german":"Jürgen Habermas'' Theorie der Öffentlichkeit hat die Medienpolitik bis heute beeinflusst: Seine These, dass eine funktionierende Demokratie eine Sphäre öffentlicher Kommunikation benötigt, in der Bürger rational diskutieren und kollektive Entscheidungen aushandeln können, begründete die normative Grundlage für öffentlich-rechtlichen Rundfunk als Gegengewicht zu kommerziellen Medien, die nach Aufmerksamkeit und nicht nach Wahrheit optimieren.","english":"Jürgen Habermas'' theory of the public sphere has influenced media policy to this day: his thesis that a functioning democracy requires a sphere of public communication in which citizens can discuss rationally and negotiate collective decisions, grounded the normative basis for public broadcasting as a counterweight to commercial media that optimise for attention and not for truth."},{"german":"Das duale Rundfunksystem in Deutschland reflektiert einen Kompromiss zwischen dem Markt und der demokratischen Funktion von Medien: Öffentlich-rechtlicher Rundfunk soll Grundversorgung mit qualitativ hochwertigen Informationen und kulturellen Inhalten sicherstellen — unabhängig von kommerziellen Interessen — während private Sender Medienvielfalt und Marktdynamik beitragen. Die Finanzierung durch den einkommensunabhängigen Rundfunkbeitrag sichert Unabhängigkeit von staatlichen und wirtschaftlichen Einflüssen.","english":"The dual broadcasting system in Germany reflects a compromise between the market and the democratic function of media: public broadcasting should ensure basic provision of high-quality information and cultural content — independent of commercial interests — while private broadcasters contribute media diversity and market dynamics. Financing through the income-independent broadcasting fee secures independence from state and economic influences."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s public broadcasting, Habermas'' public sphere theory, and media concentration at B2."}}',
'{"items":[{"word":"die Öffentlichkeit","translation":"the public sphere/public","pronunciation":"dee ÖF-fent-likh-kyt","example":"Theoretische Öffentlichkeit."},{"word":"das Gegengewicht","translation":"counterweight","pronunciation":"dahs GEH-gen-geh-vikht","example":"Als Gegengewicht dienen."},{"word":"der Rundfunkbeitrag","translation":"broadcasting fee","pronunciation":"dayr ROON-dfoonk-by-trak","example":"Monatlicher Rundfunkbeitrag."},{"word":"deliberativ","translation":"deliberative","pronunciation":"deh-li-beh-ra-TEEF","example":"Deliberative Demokratie."},{"word":"die Grundversorgung","translation":"basic provision","pronunciation":"dee GROONT-fer-zor-goong","example":"Mediale Grundversorgung."},{"word":"die Filterblase","translation":"filter bubble","pronunciation":"dee FIL-ter-blah-zeh","example":"Filterblasen im Internet."}]}',
'{"title":"X begründet die normative Grundlage für Y — X grounds the normative basis for Y","pattern":"X begründet die normative Grundlage für Y = X grounds the normative basis for Y (begründen = to ground, establish the basis for; normativ = normative, value-laden; Grundlage = basis, foundation; für = for Y — marks that X provides the value-based justification for a policy or institution)","explanation":"Begründen = to ground, establish as a basis (Grund = ground/reason; begründen = to give grounds for, to found). Normativ = normative (involving values and norms — not just empirical). Die Grundlage für Y = the basis for Y. X begründet die normative Grundlage für Y = X provides the value-based justification for Y. The pattern is used when a theory, principle, or argument justifies a practice or institution on normative (values) rather than purely pragmatic (efficiency) grounds. Compare: rechtfertigt (justifies — more practical/legal), gibt Anlass zu (gives occasion for — weaker, more incidental), liefert Argumente für (provides arguments for — less foundational), legitimiert (legitimates — more procedural/outcome-oriented).","examples":[{"sentence":"Die Idee der Menschenwürde begründet die normative Grundlage für Menschenrechte.","translation":"The idea of human dignity grounds the normative basis for human rights."},{"sentence":"Der Sozialstaatsprinzip begründet die normative Grundlage für soziale Absicherung.","translation":"The social state principle grounds the normative basis for social security."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Gegengewicht'' means?","options":["counterweight","counterbalance","opposition","corrective"],"correctAnswer":"counterweight"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Jürgen Habermas'' theory of the public sphere has influenced media policy to this day: his thesis that a functioning democracy requires a sphere of public communication in which citizens can discuss rationally and negotiate collective decisions, grounded the normative basis for public broadcasting as a counterweight to commercial media that optimise for attention and not for truth.","options":["Jürgen Habermas'' Theorie der Öffentlichkeit hat die Medienpolitik bis heute beeinflusst: Seine These, dass eine funktionierende Demokratie eine Sphäre öffentlicher Kommunikation benötigt, in der Bürger rational diskutieren und kollektive Entscheidungen aushandeln können, begründete die normative Grundlage für öffentlich-rechtlichen Rundfunk als Gegengewicht zu kommerziellen Medien, die nach Aufmerksamkeit und nicht nach Wahrheit optimieren.","Habermas argumentiert, dass öffentlicher Rundfunk kommerzielle Medien ausgleichen muss.","Öffentlich-rechtlicher Rundfunk soll dem Publikum Qualitätsnachrichten bieten, nicht Unterhaltung.","Habermas'' Öffentlichkeitstheorie rechtfertigt staatlichen Rundfunk in einer Demokratie."],"correctAnswer":"Jürgen Habermas'' Theorie der Öffentlichkeit hat die Medienpolitik bis heute beeinflusst: Seine These, dass eine funktionierende Demokratie eine Sphäre öffentlicher Kommunikation benötigt, in der Bürger rational diskutieren und kollektive Entscheidungen aushandeln können, begründete die normative Grundlage für öffentlich-rechtlichen Rundfunk als Gegengewicht zu kommerziellen Medien, die nach Aufmerksamkeit und nicht nach Wahrheit optimieren."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Idee der Menschenwürde begründet die normative Grundlage für ___.","options":["Menschenrechte","Grundrechte","Freiheiten","Schutz"],"correctAnswer":"Menschenrechte"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The social state principle grounds the normative basis for social security","wordBankItems":["Der","Sozialstaatsprinzip","begründet","die","normative","Grundlage","für","soziale","Absicherung","."],"correctAnswer":"Der Sozialstaatsprinzip begründet die normative Grundlage für soziale Absicherung ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Grundversorgung'' means?","options":["basic provision","fundamental supply","essential service","core provision"],"correctAnswer":"basic provision"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000316',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss political communication at B2","Use Politische Kommunikation vocabulary","Talk about political framing, spin, agenda-setting, and political language in Germany"],"explanation":{"intro":"Political communication vocabulary covers framing theory, agenda-setting, political spin, and German political language at B2.","culturalNote":"Politische Kommunikation: Germany: Wahlkampfkommunikation (election campaign communication — Triell instead of Duell in 2021 — three-way TV debate). Spin-Doktoren (spin doctors). Politische Sprache (political language — Neusprech/Newspeak — Orwell reference). Framing (Framing — Elisabeth Wehling Politisches Framing 2016 — how frames shape perception — refugees as ''Flüchtlingsflut'' vs. ''Menschen in Not''). Agenda-Setting (Agenda-Setting — McCombs/Shaw — media determines what people think about). Priming (political priming). Key: Politische Korrektheit (political correctness — controversy in Germany). Seehofer/Streit (CSU language). Populistische Kommunikation (populist communication — AFD — ''Wir sind das Volk''). Pressemitteilungen, Pressekonferenzen. Transparenz (transparency — FOIA — Informationsfreiheitsgesetz). Shitstorm (German word for online public outrage). Politische Büros (party offices). Politische PR vs. Journalismus."},"examples":[{"german":"Politisches Framing ist ein unvermeidlicher Aspekt öffentlicher Kommunikation: Da jeder politische Begriff ein konzeptuelles Rahmenwerk aktiviert, ist sprachliche Neutralität eine Illusion. Wer politische Themen mit Begriffen wie ''Flüchtlingsflut'' oder ''Asylmissbrauch'' rahmt, aktiviert andere emotionale Reaktionen und Wertbezüge als wer von ''Schutzsuchenden'' oder ''humanitärer Verpflichtung'' spricht — eine Asymmetrie, die strategisch genutzt werden kann und deshalb politische Aufmerksamkeit verdient.","english":"Political framing is an unavoidable aspect of public communication: since every political term activates a conceptual framework, linguistic neutrality is an illusion. Whoever frames political topics with terms like ''flood of refugees'' or ''asylum abuse'' activates different emotional reactions and value references than whoever speaks of ''people seeking protection'' or ''humanitarian obligation'' — an asymmetry that can be used strategically and therefore deserves political attention."},{"german":"Agenda-Setting beschreibt die Fähigkeit von Medien, die Themenwahrnehmung der Öffentlichkeit zu prägen: Medien bestimmen weniger, was Menschen denken, als worüber sie denken — die Selektion, Gewichtung und Rahmung von Themen in Nachrichtenformaten schlägt sich in der öffentlichen Prioritätensetzung nieder. In der digitalen Ära verschieben sich Agenda-Setting-Macht teilweise zu sozialen Medienplattformen, ohne die redaktionellen Haftungsstrukturen traditioneller Medien.","english":"Agenda-setting describes the ability of media to shape the topic perception of the public: media determines less what people think than what they think about — the selection, weighting, and framing of topics in news formats is reflected in public prioritisation. In the digital era, agenda-setting power partially shifts to social media platforms, without the editorial accountability structures of traditional media."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss political framing, agenda-setting, and the role of language in political communication at B2."}}',
'{"items":[{"word":"das Framing","translation":"framing","pronunciation":"dahs FREY-ming","example":"Politisches Framing."},{"word":"rahmen","translation":"to frame","pronunciation":"RAH-men","example":"Themen politisch rahmen."},{"word":"die Gewichtung","translation":"weighting/prioritisation","pronunciation":"dee geh-VIKHH-toong","example":"Thematische Gewichtung."},{"word":"sich niederschlagen in","translation":"to be reflected in","pronunciation":"zikh NEE-der-shla-gen in","example":"Sich in der Politik niederschlagen."},{"word":"die Selektion","translation":"selection","pronunciation":"dee ze-lek-TSYOHN","example":"Redaktionelle Selektion."},{"word":"die Haftungsstruktur","translation":"accountability structure","pronunciation":"dee HAF-toongs-shtrook-toor","example":"Redaktionelle Haftungsstrukturen."}]}',
'{"title":"X schlägt sich in Y nieder — X is reflected in Y / X manifests in Y","pattern":"X schlägt sich in Y nieder = X is reflected in Y, manifests in Y (sich niederschlagen in = to be reflected in, to manifest in — separable: schlägt...nieder; marks that X (a cause, process, or force) leaves its mark in Y (an observable outcome))","explanation":"Sich niederschlagen in = to be reflected in, to sediment in (niederschlagen = to strike down, precipitate — sich niederschlagen = to settle, be deposited; figuratively: to manifest, leave a trace in). Die Gewichtung von Themen schlägt sich in der Prioritätensetzung nieder = the weighting of topics is reflected in prioritisation. Marks that an upstream factor (selection, framing, weighting) leaves its mark in an observable downstream phenomenon (public opinion, policy priorities). Compare: sich zeigen in (to show itself in — more visual), zu sehen sein in (to be seen in — more observational), sich manifestieren in (to manifest in — stronger, more dramatic), seinen Ausdruck finden in (to find expression in — more language/symbol-focused).","examples":[{"sentence":"Die gesellschaftliche Polarisierung schlägt sich in der Wahlbeteiligung nieder.","translation":"The social polarisation is reflected in voter turnout."},{"sentence":"Strukturelle Ungleichheiten schlagen sich in Gesundheitsdaten nieder.","translation":"Structural inequalities are reflected in health data."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Rahmen'' means?","options":["to frame","to structure","to shape","to present"],"correctAnswer":"to frame"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Political framing is an unavoidable aspect of public communication: since every political term activates a conceptual framework, linguistic neutrality is an illusion. Whoever frames political topics with terms like ''flood of refugees'' or ''asylum abuse'' activates different emotional reactions and value references than whoever speaks of ''people seeking protection'' or ''humanitarian obligation'' — an asymmetry that can be used strategically and therefore deserves political attention.","options":["Politisches Framing ist ein unvermeidlicher Aspekt öffentlicher Kommunikation: Da jeder politische Begriff ein konzeptuelles Rahmenwerk aktiviert, ist sprachliche Neutralität eine Illusion. Wer politische Themen mit Begriffen wie ''Flüchtlingsflut'' oder ''Asylmissbrauch'' rahmt, aktiviert andere emotionale Reaktionen und Wertbezüge als wer von ''Schutzsuchenden'' oder ''humanitärer Verpflichtung'' spricht — eine Asymmetrie, die strategisch genutzt werden kann und deshalb politische Aufmerksamkeit verdient.","Politische Sprache ist nie neutral — Wortwahl aktiviert immer bestimmte Emotionen.","Framing zeigt, wie unterschiedliche Begriffe für dasselbe Phänomen verschiedene Reaktionen auslösen.","''Flüchtlingsflut'' und ''Schutzsuchende'' beschreiben dasselbe, werten es aber verschieden."],"correctAnswer":"Politisches Framing ist ein unvermeidlicher Aspekt öffentlicher Kommunikation: Da jeder politische Begriff ein konzeptuelles Rahmenwerk aktiviert, ist sprachliche Neutralität eine Illusion. Wer politische Themen mit Begriffen wie ''Flüchtlingsflut'' oder ''Asylmissbrauch'' rahmt, aktiviert andere emotionale Reaktionen und Wertbezüge als wer von ''Schutzsuchenden'' oder ''humanitärer Verpflichtung'' spricht — eine Asymmetrie, die strategisch genutzt werden kann und deshalb politische Aufmerksamkeit verdient."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Strukturelle Ungleichheiten schlagen sich in Gesundheitsdaten ___.","options":["nieder","unter","ab","durch"],"correctAnswer":"nieder"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The social polarisation is reflected in voter turnout","wordBankItems":["Die","gesellschaftliche","Polarisierung","schlägt","sich","in","der","Wahlbeteiligung","nieder","."],"correctAnswer":"Die gesellschaftliche Polarisierung schlägt sich in der Wahlbeteiligung nieder ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Haftungsstruktur'' means?","options":["accountability structure","liability structure","responsibility system","oversight framework"],"correctAnswer":"accountability structure"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

